"""Routes for Artifacts, generated by Dryv; the engine implements ResearchArtifactsService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated

from fastapi import APIRouter, Body, Depends, Request

from mzizi_engine.api.schemas.api.research.models.artifact_metadata import ArtifactMetadata
from mzizi_engine.api.schemas.api.research.models.artifact_ref import ArtifactRef

__all__ = ["ResearchArtifactsService", "build_research_artifacts_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class ResearchArtifactsService(ABC):
    """What Artifacts needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def inspect_artifact(self, *, ref: ArtifactRef) -> ArtifactMetadata:
        """Verify the bytes at an exact artifact reference and return their provenance."""


def build_research_artifacts_router(service: ResearchArtifactsService, guard: Guard | None = None) -> APIRouter:
    """Routes for Artifacts, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Artifacts"], dependencies=[Depends(guard)] if guard else [])

    @router.post(
        "/v1/research/inspect",
        response_model=ArtifactMetadata,
        status_code=200,
        summary="Verify the bytes at an exact artifact reference and return their provenance.",
    )
    async def inspect_artifact(
        ref: Annotated[ArtifactRef, Body()],
    ) -> ArtifactMetadata:
        return await service.inspect_artifact(ref=ref)

    return router
